fun retry(times: Int, action: (attempt: Int) -> Boolean): Boolean {
    for (attempt in 1..times) {
        if (action(attempt)) return true
    }
    return false
}

fun main() {
    val ok = retry(3) { attempt ->
        println("Attempt $attempt")
        attempt == 2
    }
    println("Succeeded: $ok")
}

