package org.example;

/** Works out the fee on a card payment: a percentage plus a fixed part, but never less than a minimum. Amounts are in cents. */
public class FeeCalculator {
    private final double percent;
    private final long fixedCents;
    private final long minimumCents;

    public FeeCalculator(double percent, long fixedCents, long minimumCents) {
        if (percent < 0 || fixedCents < 0 || minimumCents < 0) {
            throw new IllegalArgumentException("fees can't be negative");
        }
        this.percent = percent;
        this.fixedCents = fixedCents;
        this.minimumCents = minimumCents;
    }

    public static FeeCalculator standard() {
        return new FeeCalculator(1.5, 25, 50);
    }

    public double getPercent() {
        return percent;
    }

    public long feeFor(long amountCents) {
        if (amountCents <= 0) {
            throw new IllegalArgumentException("amount must be positive");
        }
        long fee = Math.round(amountCents * percent / 100) + fixedCents;
        return Math.max(fee, minimumCents);
    }

    public String describe(long amountCents) {
        return "Fee on " + amountCents + " cents: " + feeFor(amountCents) + " cents";
    }
}

package org.example;

public class Checkout {
    public static void main(String[] args) {
        FeeCalculator calculator = FeeCalculator.standard();
        System.out.println("Rate: " + calculator.getPercent() + "%");
        long[] amounts = {1000, 2500, 10000};
        for (long amount : amounts) {
            System.out.println(calculator.describe(amount));
        }
    }
}

package org.example

import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFailsWith

class FeeCalculatorTest {
    private val calculator = FeeCalculator.standard()

    @Test
    fun `small payments pay the minimum`() {
        assertEquals(50L, calculator.feeFor(1_000))
    }

    @Test
    fun `the fee is a percentage plus the fixed part`() {
        assertEquals(175L, calculator.feeFor(10_000))
    }

    @Test
    fun `half cents round up`() {
        assertEquals(63L, calculator.feeFor(2_500))
    }

    @Test
    fun `the rate is visible as a property`() {
        assertEquals(1.5, calculator.percent)
    }

    @Test
    fun `amounts must be positive`() {
        assertFailsWith<IllegalArgumentException> { calculator.feeFor(0) }
    }

    @Test
    fun `negative fees are rejected`() {
        assertFailsWith<IllegalArgumentException> { FeeCalculator(-1.0, 0, 0) }
    }
}
